package signature

// floor.go — the per-tier "signed since" downgrade floor (review R3).
//
// Purpose: remember, per tier and plugin slug, the first version that carried a release_signature, so a registry that drops the signature from a newer release cannot downgrade the check to a warning.
// Inputs: signed_since.json, embedded at build time (GENERATED by scripts/gen-signed-since.sh from the first real signed releases; P7-PLUG-71 fills free, P7-PLUG-72 licensed).
// Outputs: Floor and FloorRequires.
// Constraints: a tier with an empty floor applies no floor rule. For a non-empty floor, an entry at or above its slug's floor version, or for a slug the floor does not name (first released after signing began), must carry a signature in both compat modes. Below the floor the ordinary unsigned rule applies. An unparseable version counts as at or above the floor (fail closed).

import (
	"cmp"
	_ "embed"
	"encoding/json"
	"fmt"
	"slices"
	"strconv"
	"strings"
)

//go:embed signed_since.json
var signedSinceJSON []byte

// Floor maps tier -> slug -> first signed version. Tests swap it with
// signaturetest.UseFloor.
var Floor, floorErr = loadFloor(signedSinceJSON)

// loadFloor decodes the embedded file. A file that does not decode is an
// error, and FloorRequires then fails closed (every entry needs a signature).
func loadFloor(data []byte) (map[string]map[string]string, error) {
	var doc struct {
		Tiers map[string]map[string]string `json:"tiers"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("signature: signed_since.json: %w", err)
	}
	for _, tier := range []string{TierFree, TierLicensed} {
		if doc.Tiers[tier] == nil {
			return nil, fmt.Errorf("signature: signed_since.json: tier %q is missing or null (an empty floor is {})", tier)
		}
	}
	return doc.Tiers, nil
}

// FloorRequires reports whether an entry of tier/slug/version must carry a
// release_signature because of the floor.
func FloorRequires(tier, slug, version string) bool {
	if floorErr != nil {
		return true
	}
	m := Floor[tier]
	if len(m) == 0 {
		return false
	}
	first, named := m[slug]
	if !named {
		return true
	}
	return !versionLess(version, first)
}

// versionLess reports whether a is a strictly lower version than b. Either
// side that does not parse as MAJOR.MINOR.PATCH[-pre][+build] (optional
// leading "v") is "not less", so the floor rule applies.
func versionLess(a, b string) bool {
	pa, okA := parseVersion(a)
	pb, okB := parseVersion(b)
	if !okA || !okB {
		return false
	}
	c := slices.Compare(pa.num[:], pb.num[:])
	if c < 0 {
		return true
	}
	if c > 0 {
		return false
	}
	if pa.pre == "" {
		return false // a is the release: b is the same release or a pre-release of it
	}
	if pb.pre == "" {
		return true // a pre-release sorts below its release
	}
	return preLess(pa.pre, pb.pre)
}

// preLess orders two non-empty pre-release strings by semver 2.0.0 rules:
// dot-separated identifiers left to right, numeric ones by value and below
// alphanumeric ones, a shorter list below a longer one it prefixes.
func preLess(a, b string) bool {
	x, y := strings.Split(a, "."), strings.Split(b, ".")
	for i := 0; i < len(x) && i < len(y); i++ {
		if x[i] == y[i] {
			continue
		}
		numX, numY := isDigits(x[i]), isDigits(y[i])
		switch {
		case numX && numY:
			// Digit strings of any length: shorter is smaller, equal length compares as text.
			if len(x[i]) != len(y[i]) {
				return len(x[i]) < len(y[i])
			}
			return x[i] < y[i]
		case numX:
			return true // numeric identifiers sort below alphanumeric ones
		case numY:
			return false
		}
		return cmp.Less(x[i], y[i])
	}
	return cmp.Less(len(x), len(y))
}

type parsedVersion struct {
	num [3]int
	pre string
}

func parseVersion(s string) (parsedVersion, bool) {
	var pv parsedVersion
	s = strings.TrimPrefix(s, "v")
	s, _, _ = strings.Cut(s, "+")
	s, pre, hasPre := strings.Cut(s, "-")
	if hasPre && !validPre(pre) {
		return pv, false // "1.2.3-", "1.2.3-!" and "1.2.3-01" are not semver
	}
	pv.pre = pre
	parts := strings.Split(s, ".")
	if len(parts) != 3 {
		return pv, false
	}
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || p[0] < '0' || p[0] > '9' {
			return pv, false // Atoi also takes "+1" and "-1"; only plain digits are a version part
		}
		pv.num[i] = n
	}
	return pv, true
}

// validPre reports whether p is a semver 2.0.0 pre-release: non-empty
// dot-separated identifiers of [0-9A-Za-z-], numeric ones without a leading zero.
func validPre(p string) bool {
	for _, id := range strings.Split(p, ".") {
		if id == "" {
			return false
		}
		for _, c := range id {
			if c != '-' && (c < '0' || c > '9') && (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') {
				return false
			}
		}
		if isDigits(id) && len(id) > 1 && id[0] == '0' {
			return false
		}
	}
	return true
}

// isDigits reports whether s is a non-empty run of ASCII digits.
func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}
